import { getQuest, getWorldEvent } from '../data/catalog';
import {
  acceptQuest,
  breakthrough,
  buyItem,
  cultivate,
  eat,
  equipItem,
  equipTitle,
  escapeCombat,
  evaluateWorldEventTriggers,
  rest,
  sellItem,
  startCombat,
  talkToNpc,
  travel,
  turnInQuest,
  upgradeItem,
  useItem,
  useCombatSkill,
} from '../engine/rules';
import { appendLog, appendMessage } from './save';
import type { ActionResult, CombatSkillId, Difficulty, GameSave, Tone } from './types';
import { writeNarrationToChat } from '../services/chatMessageService';
import { generateNarration } from '../services/generationService';

export type GameAction =
  | { type: 'GAME_START'; name?: string; background?: string; abilityName?: string; abilityType?: string; difficulty?: Difficulty }
  | { type: 'TICK_NOW' }
  | { type: 'LOCATION_TRAVEL'; locationId: string }
  | { type: 'REST' }
  | { type: 'SLEEP' }
  | { type: 'EAT'; itemId?: string }
  | { type: 'CULTIVATE' }
  | { type: 'BREAKTHROUGH' }
  | { type: 'QUEST_ACCEPT'; questId: string }
  | { type: 'QUEST_TURN_IN'; questId: string }
  | { type: 'COMBAT_START'; enemyId?: string }
  | { type: 'COMBAT_SKILL_USE'; skillId: CombatSkillId }
  | { type: 'COMBAT_ESCAPE' }
  | { type: 'NPC_TALK'; npcId: string }
  | { type: 'ITEM_USE'; itemId: string }
  | { type: 'ITEM_BUY'; itemId: string }
  | { type: 'ITEM_SELL'; itemId: string }
  | { type: 'ITEM_UPGRADE'; itemId: string }
  | { type: 'EQUIPMENT_EQUIP'; itemId: string }
  | { type: 'TITLE_EQUIP'; titleId: string }
  | { type: 'NARRATION_GENERATE'; input: string };

function result(ok: boolean, save: GameSave, tone: Tone, message: string): ActionResult {
  return { ok, save, tone, message };
}

function recordAction(save: GameSave, actionType: string): GameSave {
  return { ...save, debug: { ...save.debug, lastAction: actionType } };
}

function finalize(actionType: string, outcome: { save: GameSave; ok: boolean; tone: Tone; message: string }): ActionResult {
  let nextSave = outcome.save;
  let message = outcome.message;

  if (outcome.ok) {
    const evaluated = evaluateWorldEventTriggers(nextSave);
    nextSave = evaluated.save;
    if (evaluated.triggeredEventIds.length) {
      const names = evaluated.triggeredEventIds.map(eventId => getWorldEvent(eventId)?.name || eventId).join('、');
      message = `${message} 触发事件：${names}。`;
    }
  }

  return result(outcome.ok, recordAction(nextSave, actionType), outcome.tone, message);
}

function settle(save: GameSave, actionType: string, outcome: { save: GameSave; ok: boolean; tone: Tone; message: string }): ActionResult {
  return finalize(actionType, outcome);
}

export async function dispatchGameAction(save: GameSave, action: GameAction): Promise<ActionResult> {
  try {
    switch (action.type) {
      case 'GAME_START': {
        const nextSave = appendLog(
          {
            ...save,
            stage: 'active',
            player: {
              ...save.player,
              name: action.name?.trim() || save.player.name,
              background: action.background?.trim() || save.player.background,
              abilityName: action.abilityName?.trim() || save.player.abilityName,
              abilityType: action.abilityType?.trim() || save.player.abilityType,
              difficulty: action.difficulty || save.player.difficulty,
            },
          },
          'green',
          '游戏开始',
          '裂隙纪元存档已激活。',
        );
        return finalize(action.type, { save: nextSave, ok: true, tone: 'green', message: '存档已激活。' });
      }

      case 'TICK_NOW':
        return finalize(action.type, { save: appendLog(save, 'cyan', 'tick', '已手动执行一次世界检查。'), ok: true, tone: 'cyan', message: 'tick完成。' });

      case 'LOCATION_TRAVEL':
        return settle(save, action.type, travel(save, action.locationId));

      case 'REST':
        return finalize(action.type, { save: rest(save, 2), ok: true, tone: 'green', message: '短休完成。' });

      case 'SLEEP':
        return finalize(action.type, { save: rest(save, 8), ok: true, tone: 'green', message: '睡眠完成。' });

      case 'EAT':
        return settle(save, action.type, eat(save, action.itemId));

      case 'CULTIVATE':
        return finalize(action.type, { save: cultivate(save), ok: true, tone: 'violet', message: '修炼完成。' });

      case 'BREAKTHROUGH':
        return settle(save, action.type, breakthrough(save));

      case 'QUEST_ACCEPT':
        return settle(save, action.type, acceptQuest(save, action.questId));

      case 'QUEST_TURN_IN':
        return settle(save, action.type, turnInQuest(save, action.questId));

      case 'COMBAT_START':
        return settle(save, action.type, startCombat(save, action.enemyId));

      case 'COMBAT_SKILL_USE':
        return settle(save, action.type, useCombatSkill(save, action.skillId));

      case 'COMBAT_ESCAPE':
        return settle(save, action.type, escapeCombat(save));

      case 'NPC_TALK':
        return settle(save, action.type, talkToNpc(save, action.npcId));

      case 'ITEM_USE':
        return settle(save, action.type, useItem(save, action.itemId));

      case 'ITEM_BUY':
        return settle(save, action.type, buyItem(save, action.itemId));

      case 'ITEM_SELL':
        return settle(save, action.type, sellItem(save, action.itemId));

      case 'ITEM_UPGRADE':
        return settle(save, action.type, upgradeItem(save, action.itemId));

      case 'EQUIPMENT_EQUIP':
        return settle(save, action.type, equipItem(save, action.itemId));

      case 'TITLE_EQUIP':
        return settle(save, action.type, equipTitle(save, action.titleId));

      case 'NARRATION_GENERATE': {
        const playerText = action.input.trim() || '请根据当前结算结果进行叙述。';
        const aiText = await generateNarration(save, playerText);
        const nextSave = recordAction(appendMessage(appendMessage(save, 'player', playerText), 'ai', aiText), action.type);
        await writeNarrationToChat(playerText, aiText);
        return result(true, nextSave, 'violet', 'AI叙述已生成。');
      }

      default:
        return result(false, save, 'red', '未知动作。');
    }
  } catch (error) {
    const text = error instanceof Error ? error.message : String(error);
    return result(false, appendLog(save, 'red', 'Action错误', text), 'red', text);
  }
}

export function getQuestProgressText(save: GameSave, questId: string): string {
  const quest = getQuest(questId);
  if (!quest) return '未知任务';
  return `${save.quests.progress[quest.targetEvent] || 0}/${quest.targetCount}`;
}
