import { getLocation, getQuest } from '../data/catalog';
import { appendLog } from '../core/save';
import type { GameSave, QuestDefinition, Tone } from '../core/types';
import { checkConditions, formatFailedConditions } from './conditionEngine';
import { activateWorldEvents, completeWorldEvents } from './eventEngine';
import { applyFactionReputationRewards, grantFactionMemberships } from './factionEngine';
import { changeInventory } from './inventoryEngine';
import { grantTitles } from './titleEngine';
import { refreshUnlockedLocations } from './worldEngine';
import { buildQuestCompletionFeedback, buildQuestUnlockFeedback } from './questRewardEngine';

export type QuestAvailability = {
  available: boolean;
  reason: string;
};

export function recordQuestEvent(save: GameSave, eventId: string, amount = 1): GameSave {
  const progress = { ...save.quests.progress, [eventId]: (save.quests.progress[eventId] || 0) + amount };
  return { ...save, quests: { ...save.quests, progress } };
}

export function getQuestAvailability(save: GameSave, quest: QuestDefinition): QuestAvailability {
  if (save.quests.accepted.includes(quest.id) || save.quests.completed.includes(quest.id)) {
    return { available: true, reason: '' };
  }

  if (quest.locationId && save.world.currentLocationId !== quest.locationId) {
    return { available: false, reason: `需前往${getLocation(quest.locationId)?.name || quest.locationId}接取。` };
  }

  const check = checkConditions(save, quest.unlockConditions);
  if (!check.ok) {
    return { available: false, reason: quest.unlockHint || formatFailedConditions(check) };
  }

  return { available: true, reason: '' };
}

export function acceptQuest(save: GameSave, questId: string): { save: GameSave; ok: boolean; tone: Tone; message: string } {
  const quest = getQuest(questId);
  if (!quest) return { save, ok: false, tone: 'red', message: '未知任务。' };
  if (save.quests.completed.includes(questId)) return { save, ok: false, tone: 'amber', message: '任务已经完成。' };
  if (save.quests.accepted.includes(questId)) return { save, ok: false, tone: 'amber', message: '任务已经接取。' };

  const availability = getQuestAvailability(save, quest);
  if (!availability.available) return { save, ok: false, tone: 'amber', message: availability.reason };

  const nextSave = appendLog(
    { ...save, quests: { ...save.quests, accepted: [...save.quests.accepted, questId] } },
    'green',
    '任务接取',
    `已接取${quest.name}。`,
  );
  return { save: nextSave, ok: true, tone: 'green', message: `已接取任务：${quest.name}。` };
}

export function turnInQuest(save: GameSave, questId: string): { save: GameSave; ok: boolean; tone: Tone; message: string } {
  const quest = getQuest(questId);
  if (!quest) return { save, ok: false, tone: 'red', message: '未知任务。' };
  if (!save.quests.accepted.includes(questId)) return { save, ok: false, tone: 'amber', message: '尚未接取该任务。' };
  if ((save.quests.progress[quest.targetEvent] || 0) < quest.targetCount) {
    return { save, ok: false, tone: 'amber', message: '任务目标尚未完成。' };
  }

  const beforeSave = save;
  let nextSave = { ...save, player: { ...save.player, credits: save.player.credits + quest.rewardCredits } };
  Object.entries(quest.rewardItems).forEach(([itemId, count]) => {
    nextSave = changeInventory(nextSave, itemId, count);
  });
  nextSave = applyFactionReputationRewards(nextSave, quest.rewardFactionReputation);
  nextSave = grantFactionMemberships(nextSave, quest.rewardFactionMembershipIds);
  nextSave = grantTitles(nextSave, quest.rewardTitleIds);
  nextSave = activateWorldEvents(nextSave, quest.rewardEventIds);
  nextSave = completeWorldEvents(nextSave, quest.completeEventIds);
  if (quest.rewardUnlockLocationIds?.length) {
    nextSave = {
      ...nextSave,
      world: {
        ...nextSave.world,
        unlockedLocationIds: Array.from(new Set([...nextSave.world.unlockedLocationIds, ...quest.rewardUnlockLocationIds])),
      },
    };
  }
  nextSave = refreshUnlockedLocations({
    ...nextSave,
    quests: {
      ...nextSave.quests,
      accepted: nextSave.quests.accepted.filter(id => id !== questId),
      completed: [...nextSave.quests.completed, questId],
    },
  });

  const feedbackLines = buildQuestCompletionFeedback(beforeSave, nextSave, quest);
  const unlockLines = buildQuestUnlockFeedback(beforeSave, nextSave);
  nextSave = appendLog(
    nextSave,
    'green',
    '任务完成',
    `完成${quest.name}，${feedbackLines.join('；')}。`,
  );
  if (unlockLines.length) {
    nextSave = appendLog(nextSave, 'cyan', '权限解锁', unlockLines.join('；'));
  }

  const notice = unlockLines.length ? `任务完成：${quest.name}。${unlockLines.join('；')}。` : `任务完成：${quest.name}。`;
  return { save: nextSave, ok: true, tone: 'green', message: notice };
}

export function getQuestProgressText(save: GameSave, questId: string): string {
  const quest = getQuest(questId);
  if (!quest) return '未知任务';
  return `${save.quests.progress[quest.targetEvent] || 0}/${quest.targetCount}`;
}
