import { getConnectedLocationIds, getLocation, getRoute, LOCATIONS, ROUTES } from '../data/catalog';
import type { GameSave, LocationDefinition, RouteDefinition } from '../core/types';
import { checkConditions, formatFailedConditions } from './conditionEngine';

export type TravelTargetView = LocationDefinition & {
  route: RouteDefinition;
};

export type RouteStepView = {
  from: LocationDefinition;
  to: LocationDefinition;
  route: RouteDefinition;
};

export type RoutePlanView = {
  ok: boolean;
  targetLocationId: string;
  targetName: string;
  current: boolean;
  steps: RouteStepView[];
  nextLocationId?: string;
  totalMinutes: number;
  totalCost: number;
  maxDanger: number;
  summary: string;
  blockedReason?: string;
};

export function canAccessLocation(save: GameSave, locationId: string): { ok: boolean; reason: string } {
  const location = getLocation(locationId);
  if (!location) return { ok: false, reason: '未知地点。' };

  const conditionCheck = checkConditions(save, location.unlockConditions);
  if (!conditionCheck.ok) {
    return { ok: false, reason: location.unlockHint || formatFailedConditions(conditionCheck) };
  }

  if (!save.world.unlockedLocationIds.includes(locationId)) {
    return { ok: false, reason: location.unlockHint || `${location.name}尚未解锁。` };
  }

  return { ok: true, reason: '' };
}

export function refreshUnlockedLocations(save: GameSave): GameSave {
  const unlocked = LOCATIONS.filter(location => checkConditions(save, location.unlockConditions).ok).map(location => location.id);
  const currentLocationId = getLocation(save.world.currentLocationId) ? save.world.currentLocationId : 'biluo_market';

  return {
    ...save,
    world: {
      ...save.world,
      currentLocationId,
      unlockedLocationIds: Array.from(new Set([...save.world.unlockedLocationIds, ...unlocked, currentLocationId])),
      discoveredLocationIds: Array.from(new Set([...save.world.discoveredLocationIds, currentLocationId])),
    },
  };
}

export function getTravelTargets(save: GameSave): TravelTargetView[] {
  const current = getLocation(save.world.currentLocationId);
  if (!current) return [];

  return getConnectedLocationIds(current.id).flatMap(locationId => {
    const location = getLocation(locationId);
    const route = location ? getRoute(current.id, location.id) : undefined;
    if (!location || !route || !canAccessLocation(save, location.id).ok) return [];
    return [{ ...location, travelMinutes: route.minutes, travelCost: route.cost, route }];
  });
}

function getRouteNeighborIds(locationId: string): string[] {
  return ROUTES.flatMap(route => {
    if (route.from === locationId) return [route.to];
    if (route.to === locationId) return [route.from];
    return [];
  });
}

function routePlanSummary(steps: RouteStepView[], totalMinutes: number, totalCost: number): string {
  if (steps.length === 0) return '已经在目标地点。';
  const names = [steps[0].from.name, ...steps.map(step => step.to.name)];
  return `${names.join(' -> ')}；${steps.length}段，约${totalMinutes}分钟，${totalCost}信点。`;
}

export function buildRoutePlan(save: GameSave, targetLocationId: string): RoutePlanView {
  const current = getLocation(save.world.currentLocationId);
  const target = getLocation(targetLocationId);
  if (!target) {
    return {
      ok: false,
      targetLocationId,
      targetName: targetLocationId,
      current: false,
      steps: [],
      totalMinutes: 0,
      totalCost: 0,
      maxDanger: 0,
      summary: '目标地点不存在。',
      blockedReason: '目标地点不存在。',
    };
  }

  if (!current) {
    return {
      ok: false,
      targetLocationId,
      targetName: target.name,
      current: false,
      steps: [],
      totalMinutes: 0,
      totalCost: 0,
      maxDanger: target.danger,
      summary: '当前位置异常，无法规划路线。',
      blockedReason: '当前位置异常，无法规划路线。',
    };
  }

  if (current.id === target.id) {
    return {
      ok: true,
      targetLocationId,
      targetName: target.name,
      current: true,
      steps: [],
      totalMinutes: 0,
      totalCost: 0,
      maxDanger: target.danger,
      summary: '已经在目标地点。',
    };
  }

  const targetAccess = canAccessLocation(save, target.id);
  if (!targetAccess.ok) {
    return {
      ok: false,
      targetLocationId,
      targetName: target.name,
      current: false,
      steps: [],
      totalMinutes: 0,
      totalCost: 0,
      maxDanger: target.danger,
      summary: targetAccess.reason,
      blockedReason: targetAccess.reason,
    };
  }

  const open = [
    {
      locationId: current.id,
      path: [current.id],
      totalMinutes: 0,
      totalCost: 0,
      maxDanger: current.danger,
    },
  ];
  const bestScore = new Map<string, number>([[current.id, 0]]);

  while (open.length > 0) {
    open.sort((lhs, rhs) => lhs.totalMinutes + lhs.totalCost - (rhs.totalMinutes + rhs.totalCost));
    const node = open.shift()!;
    if (node.locationId === target.id) {
      const steps = node.path.slice(0, -1).flatMap((fromId, index) => {
        const toId = node.path[index + 1];
        const from = getLocation(fromId);
        const to = getLocation(toId);
        const route = getRoute(fromId, toId);
        return from && to && route ? [{ from, to, route }] : [];
      });
      return {
        ok: steps.length > 0,
        targetLocationId,
        targetName: target.name,
        current: false,
        steps,
        nextLocationId: steps[0]?.to.id,
        totalMinutes: node.totalMinutes,
        totalCost: node.totalCost,
        maxDanger: node.maxDanger,
        summary: routePlanSummary(steps, node.totalMinutes, node.totalCost),
      };
    }

    getRouteNeighborIds(node.locationId).forEach(nextId => {
      if (node.path.includes(nextId)) return;
      const nextLocation = getLocation(nextId);
      const route = getRoute(node.locationId, nextId);
      if (!nextLocation || !route) return;
      if (!canAccessLocation(save, nextId).ok) return;

      const totalMinutes = node.totalMinutes + route.minutes;
      const totalCost = node.totalCost + route.cost;
      const score = totalMinutes + totalCost;
      if ((bestScore.get(nextId) ?? Number.POSITIVE_INFINITY) <= score) return;
      bestScore.set(nextId, score);
      open.push({
        locationId: nextId,
        path: [...node.path, nextId],
        totalMinutes,
        totalCost,
        maxDanger: Math.max(node.maxDanger, route.danger, nextLocation.danger),
      });
    });
  }

  return {
    ok: false,
    targetLocationId,
    targetName: target.name,
    current: false,
    steps: [],
    totalMinutes: 0,
    totalCost: 0,
    maxDanger: target.danger,
    summary: '没有找到已解锁路线。',
    blockedReason: '没有找到已解锁路线。',
  };
}
