import { getLocation } from '../data/catalog';
import { appendLog } from '../core/save';
import type { GameSave, Tone } from '../core/types';
import { clampPercent } from './common';
import { advanceTime } from './timeEngine';

export function cultivate(save: GameSave): GameSave {
  const location = getLocation(save.world.currentLocationId);
  const locationBonus = location?.tags.includes('修炼') || location?.tags.includes('高灵力') ? 4 : 0;
  const incenseBonus = save.inventory.equipped.accessory === 'calming_charm' ? 1 : 0;
  const progressGain = 3 + locationBonus + incenseBonus + Math.floor(Math.random() * 4);
  const nextSave = advanceTime(save, 120);

  return appendLog(
    {
      ...nextSave,
      player: {
        ...nextSave.player,
        mp: clampPercent(nextSave.player.mp - 12),
        sp: clampPercent(nextSave.player.sp - 8),
        realmProgress: clampPercent(nextSave.player.realmProgress + progressGain),
      },
    },
    'violet',
    '修炼',
    `修炼进度提升 ${progressGain}%。`,
  );
}

export function breakthrough(save: GameSave): { save: GameSave; ok: boolean; tone: Tone; message: string } {
  if (save.player.realmProgress < 100) {
    return { save, ok: false, tone: 'amber', message: '境界进度未满，暂时不能突破。' };
  }
  if (save.player.hp < 45 || save.player.mp < 35 || save.player.sp < 35) {
    return { save, ok: false, tone: 'amber', message: '当前身体或灵力状态不足，强行突破风险过高。' };
  }

  const success = Math.random() < 0.72;
  if (!success) {
    const failed = appendLog(
      {
        ...advanceTime(save, 180),
        player: {
          ...save.player,
          hp: clampPercent(save.player.hp - 18),
          mp: clampPercent(save.player.mp - 30),
          injury: save.player.injury === '无伤' ? '轻伤' : save.player.injury,
          realmProgress: 78,
        },
      },
      'amber',
      '突破失败',
      '灵力冲关没有站稳，进度回退并造成轻微反噬。',
    );
    return { save: failed, ok: true, tone: 'amber', message: '突破失败，已由脚本结算反噬。' };
  }

  const stageOrder = ['初期', '中期', '后期', '巅峰'] as const;
  const nextStage = stageOrder[Math.min(stageOrder.indexOf(save.player.realmStage) + 1, stageOrder.length - 1)];
  const nextSave = appendLog(
    {
      ...advanceTime(save, 180),
      player: {
        ...save.player,
        realmStage: nextStage,
        realmProgress: 0,
        mp: clampPercent(save.player.mp - 25),
      },
    },
    'green',
    '突破成功',
    `当前小阶提升至${save.player.realm}${nextStage}。`,
  );

  return { save: nextSave, ok: true, tone: 'green', message: '突破成功。' };
}
