import { ENEMIES, getEnemy, getItem } from '../data/catalog';
import { appendLog } from '../core/save';
import type { CombatSkillId, CombatStatus, EnemyDefinition, EnemyTraitId, GameSave, Tone } from '../core/types';
import { clampPercent } from './common';
import { checkConditions } from './conditionEngine';
import { changeInventory } from './inventoryEngine';
import { recordQuestEvent } from './questEngine';

export type PlayerCombatStats = {
  attack: number;
  defense: number;
  abilityPower: number;
  guard: number;
  escape: number;
};

type CombatOutcome = { save: GameSave; ok: boolean; tone: Tone; message: string };
type CombatSkillConfig = {
  name: string;
  mpCost: number;
  spCost: number;
  baseDamage: number;
  enemyStatus?: CombatStatus;
  playerStatus?: CombatStatus;
  healHp?: number;
  ignoreArmor?: boolean;
  riftBonus?: boolean;
  counterGuard?: number;
};

const STATUS_NAMES: Record<CombatStatus['id'], string> = {
  guarded: '防守架势',
  bleeding: '流血',
  rift_erosion: '裂隙侵蚀',
  staggered: '失衡',
  marked: '破绽标记',
  weakened: '弱化',
};

const ENEMY_TRAIT_LABELS: Record<EnemyTraitId, string> = {
  armored: '厚甲',
  swift: '迅捷',
  riftTouched: '裂隙侵染',
  regenerating: '再生',
  flying: '飞行',
  cultist: '教团术式',
  beastPack: '群猎',
  corrupted: '腐化',
};

export const COMBAT_SKILL_COSTS: Record<CombatSkillId, { name: string; mpCost: number; spCost: number }> = {
  basic_strike: { name: '制式斩击', mpCost: 6, spCost: 4 },
  piercing_thrust: { name: '破甲突刺', mpCost: 10, spCost: 12 },
  ability_burst: { name: '异能爆发', mpCost: 22, spCost: 8 },
  rift_cut: { name: '裂隙斩', mpCost: 28, spCost: 14 },
  guard: { name: '防守架势', mpCost: 0, spCost: 8 },
  field_medicine: { name: '战场整备', mpCost: 8, spCost: 12 },
};

export function getPlayerCombatStats(save: GameSave): PlayerCombatStats {
  return Object.values(save.inventory.equipped).reduce(
    (stats, itemId) => {
      const item = itemId ? getItem(itemId) : undefined;
      const itemStats = item?.combatStats || {};
      return {
        attack: stats.attack + (itemStats.attack || 0),
        defense: stats.defense + (itemStats.defense || 0),
        abilityPower: stats.abilityPower + (itemStats.abilityPower || 0),
        guard: stats.guard + (itemStats.guard || 0),
        escape: stats.escape + (itemStats.escape || 0),
      };
    },
    { attack: 4, defense: 2, abilityPower: 4, guard: 0, escape: 0 },
  );
}

function createStatus(id: CombatStatus['id'], duration: number, power: number): CombatStatus {
  return { id, name: STATUS_NAMES[id], duration, power };
}

function mergeStatus(statuses: CombatStatus[], status: CombatStatus): CombatStatus[] {
  const existing = statuses.find(entry => entry.id === status.id);
  if (!existing) return [...statuses, status];
  return statuses.map(entry =>
    entry.id === status.id
      ? { ...entry, duration: Math.max(entry.duration, status.duration), power: Math.max(entry.power, status.power) }
      : entry,
  );
}

function tickStatuses(statuses: CombatStatus[] = []): CombatStatus[] {
  return statuses
    .map(status => ({ ...status, duration: status.duration - 1 }))
    .filter(status => status.duration > 0);
}

function statusPower(statuses: CombatStatus[] = [], statusId: CombatStatus['id']): number {
  return statuses.find(status => status.id === statusId)?.power || 0;
}

function enemyHasTrait(enemy: EnemyDefinition, trait: EnemyTraitId): boolean {
  return Boolean(enemy.traits?.includes(trait));
}

export function getEnemyTraitLabels(enemy?: EnemyDefinition): string[] {
  return (enemy?.traits || []).map(trait => ENEMY_TRAIT_LABELS[trait] || trait);
}

export function getEnemyCounterHints(enemy?: EnemyDefinition): string[] {
  if (!enemy) return [];
  const hints: string[] = [];
  if (enemyHasTrait(enemy, 'armored')) hints.push('厚甲：优先破甲突刺，或先打出破绽标记再换高伤技能。');
  if (enemyHasTrait(enemy, 'swift')) hints.push('迅捷：保留体力，防守架势和战场整备能降低反击压力。');
  if (enemyHasTrait(enemy, 'flying')) hints.push('飞行：普通斩击会受限，先用破甲突刺标记再输出更稳。');
  if (enemyHasTrait(enemy, 'regenerating')) hints.push('再生：裂隙斩的弱化状态可以压住恢复窗口。');
  if (enemyHasTrait(enemy, 'riftTouched')) hints.push('裂隙侵染：裂隙斩有共振加成，但要注意灵力被侵蚀。');
  if (enemyHasTrait(enemy, 'cultist')) hints.push('教团术式：裂隙斩能打共振点，低灵力时优先脱离或整备。');
  if (enemyHasTrait(enemy, 'beastPack')) hints.push('群猎：不要把体力打空，脱离成功率会被压低。');
  if (enemyHasTrait(enemy, 'corrupted')) hints.push('腐化：优先削弱和稳定防线，避免被持续污染拖入长战。');
  if ((enemy.danger || 0) >= 3) hints.push('高危：建议携带回复品，生命低于一半时先整备或脱离。');
  return hints.length ? hints : ['无明显克制关系：保持资源充足，按生命与体力节奏出手。'];
}

export function getEnemyVictoryAdvice(enemy?: EnemyDefinition): string[] {
  if (!enemy) return [];
  const advice = [`胜利后可获得${enemy.rewardCredits}信点，并推进修炼进度${enemy.rewardProgress}%。`];
  const drops = Object.entries(enemy.dropItems || {});
  if (drops.some(([itemId]) => itemId === 'rift_dust')) advice.push('裂隙尘可用于学院样本复核和灵力增幅器调谐。');
  if (drops.some(([itemId]) => itemId === 'liutie_ore')) advice.push('流铁矿砂适合装备升级，回钟鸣铺或背包页检查材料。');
  if (drops.some(([itemId]) => itemId === 'ironwood_herb')) advice.push('铁木草可用于护身饰品升级，也能支撑碧落镇材料线。');
  if (drops.some(([itemId]) => itemId === 'beast_core_shard')) advice.push('蛮兽晶核碎片是低阶武器和防具升级的通用材料。');
  if (enemy.defeatEvents?.length) advice.push('击败记录会推进关联任务；战斗结束后查看任务页能确认进度。');
  if ((enemy.danger || 0) >= 3) advice.push('高危战斗结束后建议短休、进食或使用医疗物资再继续探索。');
  return advice;
}

function appendCombatLog(save: GameSave, entries: string[]): string[] {
  return [...(save.combat.log || []), ...entries].slice(-10);
}

function applyPlayerStatusStart(save: GameSave): { save: GameSave; entries: string[]; defeated: boolean } {
  const entries: string[] = [];
  let hp = save.player.hp;
  let mp = save.player.mp;

  (save.combat.playerStatuses || []).forEach(status => {
    if (status.id === 'bleeding') {
      hp = clampPercent(hp - status.power);
      entries.push(`流血造成${status.power}点伤害。`);
    }
    if (status.id === 'rift_erosion') {
      mp = clampPercent(mp - status.power);
      entries.push(`裂隙侵蚀吞噬${status.power}点灵力。`);
    }
  });

  return {
    save: { ...save, player: { ...save.player, hp, mp } },
    entries,
    defeated: hp <= 0,
  };
}

function applyEnemyTraitStart(save: GameSave, enemy: EnemyDefinition): { save: GameSave; entries: string[] } {
  const entries: string[] = [];
  let enemyHp = save.combat.enemyHp || enemy.maxHp;
  const enemyStatuses = save.combat.enemyStatuses || [];
  const weakened = statusPower(enemyStatuses, 'weakened');

  if (enemyHasTrait(enemy, 'regenerating') && weakened <= 0 && enemyHp > 0 && enemyHp < enemy.maxHp) {
    const heal = 5 + (enemy.danger || 0) * 2;
    enemyHp = Math.min(enemy.maxHp, enemyHp + heal);
    entries.push(`${enemy.name}的再生特性恢复${heal}点生命。`);
  }

  return {
    save: { ...save, combat: { ...save.combat, enemyHp } },
    entries,
  };
}

function endCombatDefeat(save: GameSave, entries: string[]): CombatOutcome {
  const nextSave = appendLog(
    {
      ...save,
      player: { ...save.player, hp: Math.max(1, save.player.hp), injury: '濒死' },
      combat: {
        active: false,
        round: 0,
        log: appendCombatLog(save, [...entries, '你被迫脱离战斗，伤势恶化到濒死。']),
        playerStatuses: [],
        enemyStatuses: [],
        escapeAttempts: 0,
      },
    },
    'red',
    '战斗失利',
    '你被迫脱离战斗，伤势恶化到濒死。',
  );
  return { save: nextSave, ok: true, tone: 'red', message: '战斗失利：你被迫脱离战斗。' };
}

function resolveEnemyCounter(save: GameSave, enemy: EnemyDefinition, entries: string[], extraGuard = 0): CombatOutcome | { save: GameSave; entries: string[] } {
  const stats = getPlayerCombatStats(save);
  const enemyStatuses = save.combat.enemyStatuses || [];
  const staggerReduction = statusPower(enemyStatuses, 'staggered');
  const weakenedReduction = statusPower(enemyStatuses, 'weakened');
  const guardReduction = statusPower(save.combat.playerStatuses || [], 'guarded') + extraGuard;
  const traitBonus =
    (enemyHasTrait(enemy, 'swift') ? 4 : 0) +
    (enemyHasTrait(enemy, 'flying') ? 3 : 0) +
    (enemyHasTrait(enemy, 'cultist') ? 3 : 0) +
    (enemyHasTrait(enemy, 'beastPack') ? 2 : 0);
  const rawDamage = enemy.attack + (enemy.danger || 0) * 2 + traitBonus + Math.floor(Math.random() * 7);
  const enemyDamage = Math.max(1, rawDamage - stats.defense - guardReduction - staggerReduction - weakenedReduction);
  const nextHp = clampPercent(save.player.hp - enemyDamage);
  const nextPlayerStatuses = [...(save.combat.playerStatuses || [])];
  const nextEntries = [...entries, `${enemy.name}反击，造成${enemyDamage}点伤害。`];

  if (enemyHasTrait(enemy, 'swift') && Math.random() < 0.18) {
    nextEntries.push(`${enemy.name}行动极快，压缩了你的退路。`);
  }

  if ((enemyHasTrait(enemy, 'riftTouched') || enemyHasTrait(enemy, 'cultist') || enemy.tags.includes('裂隙') || enemy.tags.includes('深渊教团')) && Math.random() < 0.28) {
    nextEntries.push('裂隙气息侵蚀灵力。');
    nextPlayerStatuses.push(createStatus('rift_erosion', 3, 3));
  } else if (enemyDamage >= 18 && Math.random() < 0.35) {
    nextEntries.push('伤口持续出血。');
    nextPlayerStatuses.push(createStatus('bleeding', 2, 3));
  }

  const mergedStatuses = nextPlayerStatuses.reduce((statuses, status) => mergeStatus(statuses, status), [] as CombatStatus[]);
  const nextSave: GameSave = {
    ...save,
    player: {
      ...save.player,
      hp: nextHp,
      injury: nextHp <= 20 ? '重伤' : nextHp <= 50 ? '轻伤' : save.player.injury,
    },
    combat: {
      ...save.combat,
      round: save.combat.round + 1,
      log: appendCombatLog(save, nextEntries),
      playerStatuses: tickStatuses(mergedStatuses),
      enemyStatuses: tickStatuses(enemyStatuses),
    },
  };

  if (nextHp <= 0) return endCombatDefeat(nextSave, []);
  return { save: nextSave, entries: nextEntries };
}

export function canEncounterEnemy(save: GameSave, enemy: EnemyDefinition): { ok: boolean; reason: string } {
  const currentLocationId = save.world.currentLocationId;
  if (enemy.habitatIds && enemy.habitatIds.length > 0 && !enemy.habitatIds.includes(currentLocationId)) {
    return { ok: false, reason: '敌人不在当前地点。' };
  }

  const check = checkConditions(save, enemy.encounterConditions);
  if (!check.ok) return { ok: false, reason: check.failed.join('；') };

  return { ok: true, reason: '' };
}

export function getAvailableEnemies(save: GameSave): EnemyDefinition[] {
  return ENEMIES.filter(enemy => canEncounterEnemy(save, enemy).ok);
}

export function startCombat(save: GameSave, enemyId = 'wild_mangler'): CombatOutcome {
  if (save.combat.active) return { save, ok: false, tone: 'amber', message: '当前已经处于战斗中。' };
  const enemy = getEnemy(enemyId);
  if (!enemy) return { save, ok: false, tone: 'red', message: '未知敌人。' };

  const encounter = canEncounterEnemy(save, enemy);
  if (!encounter.ok) return { save, ok: false, tone: 'amber', message: encounter.reason };

  const nextSave = appendLog(
    {
      ...save,
      combat: {
        active: true,
        enemyId: enemy.id,
        enemyName: enemy.name,
        enemyHp: enemy.maxHp,
        enemyMaxHp: enemy.maxHp,
        round: 1,
        log: [`遭遇${enemy.name}。`],
        playerStatuses: [],
        enemyStatuses: [],
        escapeAttempts: 0,
      },
    },
    'red',
    '战斗开始',
    `你遭遇了${enemy.name}。`,
  );
  return { save: nextSave, ok: true, tone: 'red', message: `遭遇${enemy.name}。` };
}

export function useCombatSkill(save: GameSave, skillId: CombatSkillId): CombatOutcome {
  if (!save.combat.active || !save.combat.enemyId) return { save, ok: false, tone: 'amber', message: '当前没有战斗。' };
  const enemy = getEnemy(save.combat.enemyId);
  if (!enemy) return { save, ok: false, tone: 'red', message: '敌人数据缺失。' };

  const statusStart = applyPlayerStatusStart(save);
  if (statusStart.defeated) return endCombatDefeat(statusStart.save, statusStart.entries);

  const traitStart = applyEnemyTraitStart(statusStart.save, enemy);
  const workingSave = traitStart.save;
  const baseEntries = [...statusStart.entries, ...traitStart.entries];
  const stats = getPlayerCombatStats(workingSave);
  const skills: Record<CombatSkillId, CombatSkillConfig> = {
    basic_strike: { ...COMBAT_SKILL_COSTS.basic_strike, baseDamage: 18 + stats.attack },
    piercing_thrust: {
      ...COMBAT_SKILL_COSTS.piercing_thrust,
      baseDamage: 24 + stats.attack,
      enemyStatus: createStatus('marked', 2, 5),
      ignoreArmor: true,
    },
    ability_burst: { ...COMBAT_SKILL_COSTS.ability_burst, baseDamage: 34 + stats.abilityPower, enemyStatus: createStatus('staggered', 2, 6) },
    rift_cut: {
      ...COMBAT_SKILL_COSTS.rift_cut,
      baseDamage: 28 + stats.abilityPower + Math.floor(stats.attack / 2),
      enemyStatus: createStatus('weakened', 2, 7),
      riftBonus: true,
    },
    guard: { ...COMBAT_SKILL_COSTS.guard, baseDamage: 8 + Math.floor(stats.guard / 2), playerStatus: createStatus('guarded', 2, 12 + stats.guard) },
    field_medicine: {
      ...COMBAT_SKILL_COSTS.field_medicine,
      baseDamage: 0,
      healHp: 18 + Math.floor(stats.defense / 3),
      playerStatus: createStatus('guarded', 1, 6 + stats.guard),
      counterGuard: 8,
    },
  };
  const skill = skills[skillId];

  if (workingSave.player.mp < skill.mpCost) return { save, ok: false, tone: 'red', message: '灵力不足。' };
  if (workingSave.player.sp < skill.spCost) return { save, ok: false, tone: 'red', message: '体力不足。' };

  const enemyStatuses = workingSave.combat.enemyStatuses || [];
  const markedBonus = statusPower(enemyStatuses, 'marked');
  const armorPenalty = enemyHasTrait(enemy, 'armored') && !skill.ignoreArmor && markedBonus <= 0 ? 8 : 0;
  const flyingPenalty = enemyHasTrait(enemy, 'flying') && markedBonus <= 0 && skillId === 'basic_strike' ? 6 : 0;
  const riftBonus = skill.riftBonus && (enemyHasTrait(enemy, 'riftTouched') || enemyHasTrait(enemy, 'corrupted') || enemyHasTrait(enemy, 'cultist')) ? 10 : 0;
  const playerDamage = skill.baseDamage > 0 ? Math.max(1, skill.baseDamage + Math.floor(Math.random() * 10) + markedBonus + riftBonus - armorPenalty - flyingPenalty) : 0;
  const enemyHp = Math.max(0, (workingSave.combat.enemyHp || enemy.maxHp) - playerDamage);
  const entries = [...baseEntries];
  if (playerDamage > 0) {
    entries.push(`你使用${skill.name}，造成${playerDamage}点伤害。`);
  } else {
    entries.push(`你使用${skill.name}，稳住战线。`);
  }
  if (markedBonus > 0 && playerDamage > 0) entries.push('破绽标记扩大了伤害窗口。');
  if (armorPenalty > 0) entries.push(`${enemy.name}的厚甲削弱了伤害。`);
  if (flyingPenalty > 0) entries.push(`${enemy.name}保持空中机动，普通斩击受限。`);
  if (riftBonus > 0) entries.push('裂隙斩命中敌人的污染共振点。');
  if (skill.enemyStatus) entries.push(`${enemy.name}陷入${skill.enemyStatus.name}。`);
  if (skill.playerStatus) entries.push(`你获得${skill.playerStatus.name}。`);
  if (skill.healHp) entries.push(`战场整备恢复${skill.healHp}点生命。`);

  const nextEnemyStatuses = skill.enemyStatus
    ? mergeStatus(workingSave.combat.enemyStatuses || [], skill.enemyStatus)
    : workingSave.combat.enemyStatuses || [];
  const nextPlayerStatuses = skill.playerStatus
    ? mergeStatus(workingSave.combat.playerStatuses || [], skill.playerStatus)
    : workingSave.combat.playerStatuses || [];

  const afterPlayer: GameSave = {
    ...workingSave,
    player: {
      ...workingSave.player,
      hp: skill.healHp ? clampPercent(workingSave.player.hp + skill.healHp) : workingSave.player.hp,
      mp: clampPercent(workingSave.player.mp - skill.mpCost),
      sp: clampPercent(workingSave.player.sp - skill.spCost),
    },
    combat: {
      ...workingSave.combat,
      enemyHp,
      enemyStatuses: nextEnemyStatuses,
      playerStatuses: nextPlayerStatuses,
      log: appendCombatLog(workingSave, entries),
    },
  };

  if (enemyHp <= 0) return finishVictory(afterPlayer, enemy, entries);

  const counter = resolveEnemyCounter(afterPlayer, enemy, entries, skill.counterGuard || 0);
  if ('ok' in counter) return counter;
  return { save: counter.save, ok: true, tone: 'red', message: `回合结算：敌人剩余 ${enemyHp}/${enemy.maxHp}。` };
}

function finishVictory(save: GameSave, enemy: EnemyDefinition, entries: string[]): CombatOutcome {
  let rewarded: GameSave = {
    ...save,
    player: {
      ...save.player,
      credits: save.player.credits + enemy.rewardCredits,
      realmProgress: clampPercent(save.player.realmProgress + enemy.rewardProgress),
    },
    combat: {
      active: false,
      round: 0,
      log: appendCombatLog(save, [...entries, `${enemy.name}被击败。`]),
      playerStatuses: [],
      enemyStatuses: [],
      escapeAttempts: 0,
    },
  };

  Object.entries(enemy.dropItems || { beast_core_shard: 1 }).forEach(([itemId, count]) => {
    rewarded = changeInventory(rewarded, itemId, count);
  });

  Array.from(new Set(['beast_defeated', `enemy_defeated:${enemy.id}`, ...(enemy.defeatEvents || [])])).forEach(eventId => {
    rewarded = recordQuestEvent(rewarded, eventId);
  });

  const dropText = Object.entries(enemy.dropItems || { beast_core_shard: 1 })
    .map(([itemId, count]) => `${getItem(itemId)?.name || itemId}x${count}`)
    .join('、');
  rewarded = appendLog(rewarded, 'green', '战斗胜利', `获得 ${enemy.rewardCredits} 信点${dropText ? `、${dropText}` : ''}。`);
  return { save: rewarded, ok: true, tone: 'green', message: `${enemy.name}已被击败。` };
}

export function escapeCombat(save: GameSave): CombatOutcome {
  if (!save.combat.active || !save.combat.enemyId) return { save, ok: false, tone: 'amber', message: '当前没有战斗。' };
  const enemy = getEnemy(save.combat.enemyId);
  if (!enemy) return { save, ok: false, tone: 'red', message: '敌人数据缺失。' };

  const stats = getPlayerCombatStats(save);
  const attempts = save.combat.escapeAttempts || 0;
  const injuryPenalty = save.player.injury === '重伤' ? 12 : save.player.injury === '濒死' ? 25 : save.player.injury === '中伤' ? 8 : 0;
  const enemyStatuses = save.combat.enemyStatuses || [];
  const traitPenalty =
    (enemyHasTrait(enemy, 'swift') ? 10 : 0) +
    (enemyHasTrait(enemy, 'flying') ? 8 : 0) +
    (enemyHasTrait(enemy, 'beastPack') ? 5 : 0);
  const statusBonus = statusPower(enemyStatuses, 'marked') + statusPower(enemyStatuses, 'weakened');
  const chance = Math.max(
    15,
    Math.min(85, 42 + Math.floor(save.player.sp / 4) + stats.escape + statusBonus - traitPenalty - (enemy.danger || 0) * 8 - attempts * 10 - injuryPenalty),
  );
  const success = Math.random() * 100 < chance;

  if (success) {
    const nextSave = appendLog(
      {
        ...save,
        player: { ...save.player, sp: clampPercent(save.player.sp - 10) },
        combat: {
          active: false,
          round: 0,
          log: appendCombatLog(save, [`你抓住空隙脱离战斗。成功率${chance}%。`]),
          playerStatuses: [],
          enemyStatuses: [],
          escapeAttempts: 0,
        },
      },
      'amber',
      '脱离战斗',
      `你成功脱离${enemy.name}。`,
    );
    return { save: nextSave, ok: true, tone: 'amber', message: `已脱离战斗。成功率${chance}%。` };
  }

  const afterAttempt: GameSave = {
    ...save,
    player: { ...save.player, sp: clampPercent(save.player.sp - 8) },
    combat: {
      ...save.combat,
      escapeAttempts: attempts + 1,
      log: appendCombatLog(save, [`脱离失败。成功率${chance}%。`]),
    },
  };
  const counter = resolveEnemyCounter(afterAttempt, enemy, [`脱离失败。成功率${chance}%。`], 4);
  if ('ok' in counter) return counter;
  return { save: counter.save, ok: true, tone: 'red', message: `脱离失败：敌人仍在追击。成功率${chance}%。` };
}
