import { getFaction } from '../data/catalog';
import type { GameSave } from '../core/types';

export function getFactionStanding(reputation: number): string {
  if (reputation >= 80) return '盟友';
  if (reputation >= 50) return '信任';
  if (reputation >= 20) return '友善';
  if (reputation > -20) return '中立';
  if (reputation > -50) return '警惕';
  return '敌对';
}

export function changeFactionReputation(save: GameSave, factionId: string, delta: number): GameSave {
  if (!getFaction(factionId)) return save;
  const current = save.factions.reputation[factionId] || 0;
  const reputation = Math.max(-100, Math.min(100, current + delta));
  return {
    ...save,
    factions: {
      ...save.factions,
      reputation: {
        ...save.factions.reputation,
        [factionId]: reputation,
      },
    },
  };
}

export function applyFactionReputationRewards(save: GameSave, rewards: Record<string, number> = {}): GameSave {
  return Object.entries(rewards).reduce((nextSave, [factionId, delta]) => changeFactionReputation(nextSave, factionId, delta), save);
}

export function getFactionMembershipLabel(factionId: string): string {
  const faction = getFaction(factionId);
  if (!faction) return '未知身份';
  if (faction.kind === 'local') return '本地协助者';
  if (faction.kind === 'mercenary') return '登记成员';
  if (faction.kind === 'military') return '临时协作者';
  if (faction.kind === 'official') return '备案协助者';
  if (faction.kind === 'humanitarian') return '志愿协作';
  if (faction.kind === 'gray') return '交易认可';
  if (faction.kind === 'beast') return '共存盟友';
  return '协作身份';
}

export function grantFactionMembership(save: GameSave, factionId: string): GameSave {
  if (!getFaction(factionId) || save.factions.memberships.includes(factionId)) return save;
  return {
    ...save,
    factions: {
      ...save.factions,
      memberships: [...save.factions.memberships, factionId],
    },
  };
}

export function grantFactionMemberships(save: GameSave, factionIds: string[] = []): GameSave {
  return factionIds.reduce((nextSave, factionId) => grantFactionMembership(nextSave, factionId), save);
}
