import { getLocation, getRoute } from '../data/catalog';
import { appendLog } from '../core/save';
import type { GameSave, Tone } from '../core/types';
import { recordQuestEvent } from './questEngine';
import { advanceTime } from './timeEngine';
import { canAccessLocation, refreshUnlockedLocations } from './worldEngine';

export function travel(save: GameSave, locationId: string): { save: GameSave; ok: boolean; tone: Tone; message: string } {
  const syncedSave = refreshUnlockedLocations(save);
  const target = getLocation(locationId);
  if (!target) return { save, ok: false, tone: 'red', message: '未知地点。' };
  if (locationId === syncedSave.world.currentLocationId) return { save: syncedSave, ok: false, tone: 'amber', message: '你已经在这里。' };

  const access = canAccessLocation(syncedSave, locationId);
  if (!access.ok) return { save: syncedSave, ok: false, tone: 'red', message: access.reason };

  const current = getLocation(syncedSave.world.currentLocationId);
  const route = getRoute(syncedSave.world.currentLocationId, locationId);
  if (!route) {
    return { save: syncedSave, ok: false, tone: 'amber', message: `当前地点没有通往${target.name}的已知路线。` };
  }
  if (syncedSave.player.credits < route.cost) {
    return { save: syncedSave, ok: false, tone: 'red', message: '信点不足，无法支付交通费用。' };
  }

  let nextSave = appendLog(
    refreshUnlockedLocations({
      ...advanceTime(syncedSave, route.minutes),
      player: { ...syncedSave.player, credits: syncedSave.player.credits - route.cost },
      world: {
        ...syncedSave.world,
        currentLocationId: locationId,
        discoveredLocationIds: Array.from(new Set([...syncedSave.world.discoveredLocationIds, locationId])),
      },
    }),
    'cyan',
    '地点移动',
    `你从${current?.name || '当前位置'}经由${route.mode}抵达了${target.name}。${route.description}`,
  );
  nextSave = recordQuestEvent(recordQuestEvent(nextSave, 'location_visit'), `location_visit:${locationId}`);

  return { save: nextSave, ok: true, tone: 'cyan', message: `已移动到${target.name}，耗时${route.minutes}分钟。` };
}
