import {
  getEnemy,
  getFaction,
  getInitialActiveEventIds,
  getInitialFactionReputation,
  getInitialUnlockedLocationIds,
  getItem,
  getLocation,
  getQuest,
  getTitle,
  getWorldEvent,
  NPCS,
} from '../data/catalog';
import {
  GameSaveSchema,
  PROJECT_NAME,
  SAVE_SCHEMA_VERSION,
  SAVE_VARIABLE_KEY,
  type GameLog,
  type GameMessage,
  type GameSave,
  type Tone,
} from './types';

let fallbackSave: GameSave | null = null;

export function nowMs(): number {
  return Date.now();
}

export function createId(prefix: string): string {
  const id = typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`;
  return `${prefix}-${id}`;
}

export function getPeriod(hour: number): string {
  if (hour >= 5 && hour < 7) return '黎明';
  if (hour >= 7 && hour < 9) return '早晨';
  if (hour >= 9 && hour < 12) return '上午';
  if (hour >= 12 && hour < 13) return '正午';
  if (hour >= 13 && hour < 17) return '下午';
  if (hour >= 17 && hour < 19) return '傍晚';
  if (hour >= 19 && hour < 23) return '夜晚';
  if (hour >= 23 || hour < 2) return '深夜';
  return '凌晨';
}

export function getSeason(month: number): string {
  if (month <= 3) return '春';
  if (month <= 6) return '夏';
  if (month <= 9) return '秋';
  return '冬';
}

