function cloneSave(save: GameSave): GameSave {
  return JSON.parse(JSON.stringify(save)) as GameSave;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value && typeof value === 'object' && !Array.isArray(value));
}

function recordPart<T extends object>(value: unknown): Partial<T> {
  return isRecord(value) ? (value as Partial<T>) : {};
}

function arrayPart<T>(value: unknown, fallback: T[] = []): T[] {
  return Array.isArray(value) ? (value as T[]) : fallback;
}

function numberPart(value: unknown, fallback: number): number {
  return Number.isFinite(value) ? Number(value) : fallback;
}

function numberRecordPart(value: unknown, fallback: Record<string, number>, minimum = 0, keepZero = true): Record<string, number> {
  const next = { ...fallback };
  Object.entries(recordPart<Record<string, unknown>>(value)).forEach(([key, entry]) => {
    const number = Number(entry);
    if (!Number.isFinite(number) || number < minimum || (!keepZero && number === 0)) return;
    next[key] = number;
  });
  return next;
}

function uniqueKnownStrings(value: unknown, fallback: string[], exists: (id: string) => boolean): string[] {
  return Array.from(new Set(arrayPart<string>(value, fallback).filter(entry => typeof entry === 'string' && exists(entry))));
}

function knownNumberRecord(value: unknown, fallback: Record<string, number>, exists: (id: string) => boolean, minimum = 0, keepZero = true): Record<string, number> {
  return Object.fromEntries(
    Object.entries(numberRecordPart(value, fallback, minimum, keepZero)).filter(([id, count]) => exists(id) && Number.isFinite(count)),
  );
}

function stringPart(value: unknown, fallback: string): string {
  return typeof value === 'string' && value.trim() ? value : fallback;
}

function clampSavePercent(value: unknown, fallback: number): number {
  return Math.max(0, Math.min(100, Math.round(numberPart(value, fallback))));
}

export function normalizeGameSave(raw: unknown): GameSave {
  const parsed = GameSaveSchema.safeParse(raw);
  const root = parsed.success ? parsed.data : raw;
  if (!isRecord(root)) return createInitialGameSave();

  const save = root as Partial<GameSave>;
  const base = createInitialGameSave();
  const player = recordPart<GameSave['player']>(save.player);
  const time = recordPart<GameSave['time']>(save.time);
  const world = recordPart<GameSave['world']>(save.world);
  const inventory = recordPart<GameSave['inventory']>(save.inventory);
  const quests = recordPart<GameSave['quests']>(save.quests);
  const npcs = recordPart<GameSave['npcs']>(save.npcs);
  const factions = recordPart<GameSave['factions']>(save.factions);
  const titles = recordPart<GameSave['titles']>(save.titles);
  const events = recordPart<GameSave['events']>(save.events);
  const combat = recordPart<GameSave['combat']>(save.combat);
  const narrative = recordPart<GameSave['narrative']>(save.narrative);
  const debug = recordPart<GameSave['debug']>(save.debug);
  const titleOwned = uniqueKnownStrings(titles.owned, base.titles.owned, titleId => Boolean(getTitle(titleId)));
  const equippedTitle = typeof titles.equipped === 'string' && titleOwned.includes(titles.equipped) ? titles.equipped : titleOwned[0];
  const stage = save.stage === 'new' || save.stage === 'active' || save.stage === 'ended' ? save.stage : base.stage;
  const combatEnemy = typeof combat.enemyId === 'string' ? getEnemy(combat.enemyId) : undefined;
  const combatActive = Boolean(combat.active && combatEnemy && Number.isFinite(combat.enemyHp));
  const combatEnemyMaxHp = combatActive ? Math.max(1, numberPart(combat.enemyMaxHp, combatEnemy?.maxHp || 1)) : undefined;
  const combatEnemyHp = combatActive ? Math.max(0, Math.min(combatEnemyMaxHp || 1, numberPart(combat.enemyHp, combatEnemyMaxHp || 1))) : undefined;
  const inventoryItems = knownNumberRecord(inventory.items, base.inventory.items, itemId => Boolean(getItem(itemId)), 0, false);
  const equipped = recordPart<GameSave['inventory']['equipped']>(inventory.equipped);
  const normalizedEquipped = Object.fromEntries(
    Object.entries(equipped).filter(([, itemId]) => typeof itemId === 'string' && Boolean(getItem(itemId)) && (inventoryItems[itemId] || 0) > 0),
  ) as GameSave['inventory']['equipped'];
  const currentLocationId = getLocation(stringPart(world.currentLocationId, base.world.currentLocationId))
    ? stringPart(world.currentLocationId, base.world.currentLocationId)
    : base.world.currentLocationId;
  const unlockedLocationIds = uniqueKnownStrings(world.unlockedLocationIds, base.world.unlockedLocationIds, locationId => Boolean(getLocation(locationId)));
  const discoveredLocationIds = uniqueKnownStrings(world.discoveredLocationIds, base.world.discoveredLocationIds, locationId => Boolean(getLocation(locationId)));
  const activeEventIds = uniqueKnownStrings(world.activeEventIds, base.world.activeEventIds, eventId => Boolean(getWorldEvent(eventId)));
  const acceptedQuests = uniqueKnownStrings(quests.accepted, base.quests.accepted, questId => Boolean(getQuest(questId)));
  const completedQuests = uniqueKnownStrings(quests.completed, base.quests.completed, questId => Boolean(getQuest(questId)));
  const factionMemberships = uniqueKnownStrings(factions.memberships, base.factions.memberships, factionId => Boolean(getFaction(factionId)));
  const completedEventIds = uniqueKnownStrings(events.completedEventIds, base.events.completedEventIds, eventId => Boolean(getWorldEvent(eventId)));

  return {
    ...base,
    ...save,
    schemaVersion: SAVE_SCHEMA_VERSION,
    saveId: stringPart(save.saveId, base.saveId),
    saveName: stringPart(save.saveName, base.saveName),
    createdAt: numberPart(save.createdAt, base.createdAt),
    savedAt: numberPart(save.savedAt, base.savedAt),
    lastTickAt: numberPart(save.lastTickAt, base.lastTickAt),
    stage,
    player: {
      ...base.player,
      ...player,
      hp: clampSavePercent(player.hp, base.player.hp),
      mp: clampSavePercent(player.mp, base.player.mp),
      sp: clampSavePercent(player.sp, base.player.sp),
      realmProgress: clampSavePercent(player.realmProgress, base.player.realmProgress),
      credits: Math.max(0, numberPart(player.credits, base.player.credits)),
      sourceCrystals: Math.max(0, numberPart(player.sourceCrystals, base.player.sourceCrystals)),
      darkChips: Math.max(0, numberPart(player.darkChips, base.player.darkChips)),
    },
    time: {
      ...base.time,
      ...time,
      year: numberPart(time.year, base.time.year),
      month: Math.max(1, Math.min(12, numberPart(time.month, base.time.month))),
      day: Math.max(1, Math.min(31, numberPart(time.day, base.time.day))),
      hour: Math.max(0, Math.min(23, numberPart(time.hour, base.time.hour))),
      turn: Math.max(0, numberPart(time.turn, base.time.turn)),
      period: getPeriod(numberPart(time.hour, base.time.hour)),
      season: getSeason(numberPart(time.month, base.time.month)),
    },
    world: {
      ...base.world,
      ...world,
      currentLocationId,
      unlockedLocationIds,
      discoveredLocationIds: Array.from(new Set([...discoveredLocationIds, currentLocationId])),
      activeEventIds,
    },
    inventory: {
      ...base.inventory,
      ...inventory,
      items: inventoryItems,
      equipped: normalizedEquipped,
    },
    quests: {
      ...base.quests,
      ...quests,
      accepted: acceptedQuests.filter(questId => !completedQuests.includes(questId)),
      completed: completedQuests,
      progress: numberRecordPart(quests.progress, base.quests.progress, 0),
    },
    npcs: {
      ...base.npcs,
      ...npcs,
      relations: {
        ...base.npcs.relations,
        ...(recordPart<GameSave['npcs']['relations']>(npcs.relations) as GameSave['npcs']['relations']),
      },
    },
    logs: Array.isArray(save.logs) ? save.logs.slice(0, 80) : [],
    messages: Array.isArray(save.messages) ? save.messages.slice(-80) : [],
    factions: {
      ...base.factions,
      ...factions,
      memberships: factionMemberships,
      reputation: {
        ...base.factions.reputation,
        ...knownNumberRecord(factions.reputation, {}, factionId => Boolean(getFaction(factionId)), -999),
      },
    },
    titles: {
      ...base.titles,
      ...titles,
      owned: titleOwned,
      equipped: equippedTitle,
    },
    events: {
      ...base.events,
      ...events,
      completedEventIds,
      flags: recordPart<Record<string, boolean>>(events.flags) as Record<string, boolean>,
      records: arrayPart(events.records, base.events.records).slice(0, 80),
    },
    combat: {
      ...base.combat,
      ...combat,
      active: combatActive,
      round: combatActive ? Math.max(1, numberPart(combat.round, 1)) : 0,
      enemyId: combatActive ? combat.enemyId : undefined,
      enemyName: combatActive ? stringPart(combat.enemyName, combatEnemy?.name || '未知敌人') : undefined,
      enemyHp: combatEnemyHp,
      enemyMaxHp: combatEnemyMaxHp,
      log: arrayPart<string>(combat.log, base.combat.log).filter(entry => typeof entry === 'string').slice(-8),
      playerStatuses: arrayPart(combat.playerStatuses, base.combat.playerStatuses),
      enemyStatuses: arrayPart(combat.enemyStatuses, base.combat.enemyStatuses),
      escapeAttempts: Math.max(0, numberPart(combat.escapeAttempts, 0)),
    },
    narrative: {
      ...base.narrative,
      ...narrative,
      entries: arrayPart(narrative.entries, base.narrative.entries)
        .filter(entry => isRecord(entry) && typeof entry.text === 'string')
        .slice(0, 120) as GameSave['narrative']['entries'],
      totalCount: Math.max(0, numberPart(narrative.totalCount, arrayPart(narrative.entries, []).length)),
      summaryCount: Math.max(0, numberPart(narrative.summaryCount, base.narrative.summaryCount)),
      latestSummary: typeof narrative.latestSummary === 'string' ? narrative.latestSummary : base.narrative.latestSummary,
      pendingSummary: Boolean(narrative.pendingSummary),
      keepTemporaryChat: Boolean(narrative.keepTemporaryChat),
      lastActionTrace: isRecord(narrative.lastActionTrace) ? (narrative.lastActionTrace as GameSave['narrative']['lastActionTrace']) : undefined,
      lastCleanup: isRecord(narrative.lastCleanup) ? (narrative.lastCleanup as GameSave['narrative']['lastCleanup']) : undefined,
    },
    debug: {
      ...base.debug,
      ...debug,
      errors: arrayPart<string>(debug.errors, base.debug.errors),
    },
  };
}

function parsePossiblyWrappedJson(text: string): unknown {
  const trimmed = text.trim();
  try {
    return JSON.parse(trimmed);
  } catch {
    const fenced = trimmed.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    if (fenced) return JSON.parse(fenced[1]);

    const firstBrace = trimmed.indexOf('{');
    const lastBrace = trimmed.lastIndexOf('}');
    if (firstBrace >= 0 && lastBrace > firstBrace) {
      return JSON.parse(trimmed.slice(firstBrace, lastBrace + 1));
    }
    throw Error('导入文本不是有效 JSON，也没有找到可解析的 JSON 代码块。');
  }
}

function readStoredSave(): GameSave | null {
  if (typeof getVariables !== 'function') return fallbackSave;
  const variables = getVariables({ type: 'chat' });
  const stored = variables[SAVE_VARIABLE_KEY];
  if (!stored) return null;
  const raw = typeof stored === 'string' ? JSON.parse(stored) : stored;
  const candidate = isRecord(raw) ? raw.save || raw[SAVE_VARIABLE_KEY] || raw : raw;
  return normalizeGameSave(typeof candidate === 'string' ? JSON.parse(candidate) : candidate);
}

export function loadGameSave(): GameSave {
  try {
    const stored = readStoredSave();
    if (stored) return stored;
  } catch {
    // A broken save should not block the client. The debug panel can expose repair later.
  }
  return persistGameSave(createInitialGameSave());
}

export function persistGameSave(save: GameSave): GameSave {
  const nextSave = cloneSave({ ...save, savedAt: nowMs() });
  fallbackSave = nextSave;

  if (typeof getVariables === 'function' && typeof replaceVariables === 'function') {
    const variables = getVariables({ type: 'chat' });
    variables[SAVE_VARIABLE_KEY] = nextSave;
    replaceVariables(variables, { type: 'chat' });
  }

  return nextSave;
}

export function exportGameSaveText(save: GameSave): string {
  return JSON.stringify({ kind: SAVE_VARIABLE_KEY, exportedAt: nowMs(), save }, null, 2);
}

export function importGameSaveText(text: string): GameSave {
  if (!text.trim()) throw Error('导入文本为空。');
  const parsed = parsePossiblyWrappedJson(text);
  const candidate = isRecord(parsed) ? parsed.save || parsed[SAVE_VARIABLE_KEY] || parsed : parsed;
  return normalizeGameSave(typeof candidate === 'string' ? JSON.parse(candidate) : candidate);
}

export function appendLog(save: GameSave, tone: Tone, title: string, message: string): GameSave {
  const log: GameLog = { id: createId('log'), createdAt: nowMs(), tone, title, message };
  return { ...save, logs: [log, ...save.logs].slice(0, 80) };
}

export function appendMessage(save: GameSave, role: GameMessage['role'], text: string): GameSave {
  const message: GameMessage = { id: createId('msg'), createdAt: nowMs(), role, text };
  return { ...save, messages: [...save.messages, message].slice(-80) };
}
