import { getEnemy, getFaction, getLocation, getTitle, getWorldEvent } from '../data/catalog';
import type { GameSave } from '../core/types';
import { getEnemyTraitLabels, getFactionMembershipLabel, getFactionStanding } from '../engine/rules';
import { buildWorldbookScanText } from './worldbookRouteService';

export function buildSituationSummary(save: GameSave): string {
  const location = getLocation(save.world.currentLocationId);
  const topFactions = Object.entries(save.factions.reputation)
    .sort(([, lhs], [, rhs]) => Math.abs(rhs) - Math.abs(lhs))
    .slice(0, 3)
    .map(([factionId, reputation]) => `${getFaction(factionId)?.name || factionId}${reputation}(${getFactionStanding(reputation)})`);
  const equippedTitle = save.titles.equipped ? getTitle(save.titles.equipped)?.name || save.titles.equipped : '无';
  const memberships = save.factions.memberships.map(factionId => `${getFaction(factionId)?.name || factionId}(${getFactionMembershipLabel(factionId)})`);
  const activeEvents = save.world.activeEventIds.map(eventId => getWorldEvent(eventId)?.name || eventId).slice(0, 4);
  const combatEnemy = save.combat.enemyId ? getEnemy(save.combat.enemyId) : undefined;
  const combatTraits = getEnemyTraitLabels(combatEnemy);
  return [
    `玩家:${save.player.name} / ${save.player.background}`,
    `位置:${location?.name || save.world.currentLocationId}`,
    `时间:裂隙纪元${save.time.year}年${save.time.month}月${save.time.day}日 ${save.time.period}`,
    `状态:HP ${save.player.hp}% / MP ${save.player.mp}% / SP ${save.player.sp}% / 伤势 ${save.player.injury}`,
    `修炼:${save.player.rank} ${save.player.realm}${save.player.realmStage} 进度${save.player.realmProgress}%`,
    `异能:${save.player.abilityName}（${save.player.abilityType}）`,
    `经济:${save.player.credits}信点 / ${save.player.sourceCrystals}源晶 / ${save.player.darkChips}暗筹`,
    `称号:${equippedTitle}`,
    `势力:${topFactions.join(' / ') || '无'}`,
    `势力身份:${memberships.join(' / ') || '无'}`,
    `活跃事件:${activeEvents.join(' / ') || '无'}`,
    `任务:已接${save.quests.accepted.length} / 已完成${save.quests.completed.length}`,
    `战斗:${save.combat.active ? `${save.combat.enemyName} ${save.combat.enemyHp}/${save.combat.enemyMaxHp} 特性:${combatTraits.join('/') || '无'}` : '无'}`,
    `最近结算:${save.logs[0]?.title || '无'} - ${save.logs[0]?.message || '无'}`,
  ].join('\n');
}

export async function generateNarration(save: GameSave, playerInput: string): Promise<string> {
  const situation = buildSituationSummary(save);
  const scanText = buildWorldbookScanText(save);
  const fallback = [
    '系统结算已经完成。',
    `当前局势：${situation}`,
    'AI生成接口暂不可用，因此这里先显示本地叙述占位。后续在酒馆中运行时会调用 generate。',
  ].join('\n\n');

  if (typeof generate !== 'function') return fallback;

  return generate({
    user_input: playerInput || '请根据当前权威局势进行一段简洁的场景叙述。',
    should_stream: true,
    max_chat_history: 24,
    injects: [
      {
        position: 'none',
        depth: 0,
        role: 'system',
        should_scan: true,
        content: scanText,
      },
      {
        position: 'in_chat',
        depth: 0,
        role: 'system',
        should_scan: false,
        content: [
          '你现在只负责AIRP、场景叙述、NPC反应、气氛和建议。',
          '所有资源、战斗、修炼、地点、任务、物品、好感变化都已经由前端脚本决定。',
          '不要输出变量更新、JSON、MVU命令、函数调用或世界书编辑指令。',
          '',
          '当前权威局势:',
          situation,
        ].join('\n'),
      },
    ],
  });
}
