export function markCurrentChatTail(): number | null {
  if (typeof getLastMessageId !== 'function') return null;

  try {
    return getLastMessageId();
  } catch {
    return null;
  }
}

export async function cleanupChatMessagesAfter(mark: number | null): Promise<number> {
  if (mark === null || typeof getLastMessageId !== 'function') return 0;

  try {
    const lastMessageId = getLastMessageId();
    if (lastMessageId <= mark) return 0;

    const messageIds = Array.from({ length: lastMessageId - mark }, (_, index) => mark + index + 1);
    if (typeof deleteChatMessages === 'function') {
      await deleteChatMessages(messageIds, { refresh: 'affected' });
      return messageIds.length;
    }

    if (typeof SillyTavern !== 'undefined' && typeof SillyTavern.deleteLastMessage === 'function') {
      for (let index = 0; index < messageIds.length; index += 1) {
        await SillyTavern.deleteLastMessage();
      }
      return messageIds.length;
    }
  } catch (error) {
    console.warn('[裂隙纪元] 临时酒馆楼层清理失败', error);
  }

  return 0;
}

export async function writeNarrationToChat(playerText: string, aiText: string): Promise<number> {
  if (typeof createChatMessages !== 'function') return 0;

  const mark = markCurrentChatTail();
  await createChatMessages(
    [
      {
        role: 'user',
        name: '{{user}}',
        is_hidden: true,
        message: playerText,
        data: {},
        extra: { riftEraFrontend: { type: 'temporary_player_action', savedAt: Date.now() } },
      },
      {
        role: 'assistant',
        is_hidden: true,
        message: aiText,
        data: {},
        extra: { riftEraFrontend: { type: 'temporary_ai_narration', savedAt: Date.now() } },
      },
    ],
    { insert_before: 'end', refresh: 'none' },
  );

  return cleanupChatMessagesAfter(mark);
}
