import { teleportStyle } from '@util/script';
import App from './App.vue';
import './styles/global.css';
$(() => {
    const parentDoc = window.parent.document;
    const pinia = createPinia();
    let app = null;
    let iframeEl = null;
    let escapeButtonEl = null;
    let styleDestroy = null;
    function unmountConsole() {
        if (app) {
            app.unmount();
            app = null;
        }
        if (styleDestroy) {
            styleDestroy();
            styleDestroy = null;
        }
        if (iframeEl) {
            iframeEl.remove();
            iframeEl = null;
        }
        if (escapeButtonEl) {
            escapeButtonEl.remove();
            escapeButtonEl = null;
        }
    }
    function mountAppIntoIframe(iframe) {
        if (app || iframeEl !== iframe)
            return;
        const iframeDoc = iframe.contentDocument;
        if (!iframeDoc?.body)
            return;
        const { destroy } = teleportStyle(iframeDoc.head);
        styleDestroy = destroy;
        app = createApp(App, { onExit: unmountConsole }).use(pinia);
        app.mount(iframeDoc.body);
        if (escapeButtonEl)
            escapeButtonEl.hidden = true;
    }
    function mountEscapeButton() {
        if (escapeButtonEl)
            return;
        const button = parentDoc.createElement('button');
        button.type = 'button';
        button.textContent = '退出裂隙纪元';
        button.style.cssText = [
            'position:fixed',
            'top:14px',
            'right:14px',
            'z-index:100000',
            'height:34px',
            'padding:0 12px',
            'border:1px solid rgba(150,190,196,.42)',
            'border-radius:7px',
            'background:rgba(16,24,28,.94)',
            'color:#edf3f5',
            'font:12px/1 "Microsoft YaHei UI","Segoe UI",system-ui,sans-serif',
            'letter-spacing:0',
            'cursor:pointer',
        ].join(';');
        button.addEventListener('click', unmountConsole);
        parentDoc.body.appendChild(button);
        escapeButtonEl = button;
    }
    function mountConsole() {
        if (app || iframeEl)
            return;
        mountEscapeButton();
        const iframe = document.createElement('iframe');
        iframe.setAttribute('script_id', getScriptId());
        iframe.setAttribute('frameborder', '0');
        iframe.setAttribute('title', '裂隙纪元前端版');
        iframe.style.cssText = [
            'position:fixed',
            'inset:0',
            'width:100vw',
            'height:100vh',
            'z-index:99999',
            'border:none',
            'background:#101417',
        ].join(';');
        iframe.addEventListener('load', () => mountAppIntoIframe(iframe));
        iframeEl = iframe;
        parentDoc.body.appendChild(iframe);
        window.setTimeout(() => mountAppIntoIframe(iframe), 0);
    }
    replaceScriptButtons([{ name: '进入裂隙纪元', visible: true }]);
    eventOn(getButtonEvent('进入裂隙纪元'), mountConsole);
    mountConsole();
    $(window).on('pagehide', () => {
        unmountConsole();
    });
});
