const ACTION_LABELS: Record<string, string> = {
  GAME_START: '开局',
  TICK_NOW: '世界检查',
  LOCATION_TRAVEL: '移动',
  REST: '短休',
  SLEEP: '睡眠',
  EAT: '进食',
  CULTIVATE: '修炼',
  BREAKTHROUGH: '突破',
  QUEST_ACCEPT: '接取任务',
  QUEST_TURN_IN: '提交任务',
  COMBAT_START: '遭遇战',
  COMBAT_SKILL_USE: '战斗行动',
  COMBAT_ESCAPE: '脱离战斗',
  NPC_TALK: '交谈',
  ITEM_USE: '使用物品',
  ITEM_BUY: '购买',
  ITEM_SELL: '出售',
  ITEM_UPGRADE: '强化',
  EQUIPMENT_EQUIP: '装备',
  TITLE_EQUIP: '称号',
  NARRATION_GENERATE: '手动正文',
};

export function shouldActionCreateNarrative(action: GameAction): boolean {
  return action.type !== 'NARRATION_GENERATE';
}

function nameForActionTarget(action: GameAction): string[] {
  switch (action.type) {
    case 'LOCATION_TRAVEL':
      return [getLocation(action.locationId)?.name || action.locationId];
    case 'QUEST_ACCEPT':
    case 'QUEST_TURN_IN':
      return [getQuest(action.questId)?.name || action.questId];
    case 'COMBAT_START':
      return [getEnemy(action.enemyId || 'wild_mangler')?.name || action.enemyId || '野外敌人'];
    case 'COMBAT_SKILL_USE':
      return [COMBAT_SKILL_COSTS[action.skillId]?.name || action.skillId];
    case 'NPC_TALK':
      return [getNpc(action.npcId)?.name || action.npcId];
    case 'ITEM_USE':
    case 'ITEM_BUY':
    case 'ITEM_SELL':
    case 'ITEM_UPGRADE':
    case 'EQUIPMENT_EQUIP':
      return [getItem(action.itemId)?.name || action.itemId];
    case 'TITLE_EQUIP':
      return [getTitle(action.titleId)?.name || action.titleId];
    case 'GAME_START':
      return [action.name?.trim() || '{{user}}'];
    default:
      return [];
  }
}

function diffNumber(label: string, before: number, after: number): string | null {
  if (before === after) return null;
  const sign = after > before ? '+' : '';
  return `${label} ${before} -> ${after} (${sign}${after - before})`;
}

function diffString(label: string, before?: string, after?: string): string | null {
  if (!before || !after || before === after) return null;
  return `${label} ${before} -> ${after}`;
}

function diffArray(label: string, before: string[], after: string[], nameOf: (id: string) => string): string[] {
  const beforeSet = new Set(before);
  const afterSet = new Set(after);
  const added = after.filter(id => !beforeSet.has(id)).map(nameOf);
  const removed = before.filter(id => !afterSet.has(id)).map(nameOf);
  return [
    added.length ? `${label}新增：${added.join('、')}` : '',
    removed.length ? `${label}移除：${removed.join('、')}` : '',
  ].filter(Boolean);
}

function diffInventory(before: GameSave, after: GameSave): string[] {
  const itemIds = Array.from(new Set([...Object.keys(before.inventory.items), ...Object.keys(after.inventory.items)]));
  return itemIds
    .map(itemId => {
      const beforeCount = before.inventory.items[itemId] || 0;
      const afterCount = after.inventory.items[itemId] || 0;
      if (beforeCount === afterCount) return '';
      const itemName = getItem(itemId)?.name || itemId;
      return `${itemName} ${beforeCount} -> ${afterCount}`;
    })
    .filter(Boolean)
    .slice(0, 8);
}

function compactChanges(before: GameSave, after: GameSave): string[] {
  const beforeLocation = getLocation(before.world.currentLocationId)?.name || before.world.currentLocationId;
  const afterLocation = getLocation(after.world.currentLocationId)?.name || after.world.currentLocationId;
  const directChanges = [
    diffString('地点', beforeLocation, afterLocation),
    diffNumber('回合', before.time.turn, after.time.turn),
    diffNumber('HP', before.player.hp, after.player.hp),
    diffNumber('MP', before.player.mp, after.player.mp),
    diffNumber('SP', before.player.sp, after.player.sp),
    diffNumber('修炼进度', before.player.realmProgress, after.player.realmProgress),
    diffNumber('信点', before.player.credits, after.player.credits),
    diffNumber('源晶', before.player.sourceCrystals, after.player.sourceCrystals),
    diffNumber('暗筹', before.player.darkChips, after.player.darkChips),
    diffString('境界', `${before.player.realm}${before.player.realmStage}`, `${after.player.realm}${after.player.realmStage}`),
    diffString('伤势', before.player.injury, after.player.injury),
    diffString('饥饿', before.player.hunger, after.player.hunger),
    diffString('疲劳', before.player.fatigue, after.player.fatigue),
    before.combat.active !== after.combat.active ? `战斗 ${before.combat.active ? '进行中' : '无'} -> ${after.combat.active ? '进行中' : '无'}` : null,
    diffNumber('敌方HP', before.combat.enemyHp || 0, after.combat.enemyHp || 0),
  ].filter(Boolean) as string[];

  return [
    ...directChanges,
    ...diffInventory(before, after),
    ...diffArray('任务', before.quests.accepted, after.quests.accepted, questId => getQuest(questId)?.name || questId),
    ...diffArray('完成任务', before.quests.completed, after.quests.completed, questId => getQuest(questId)?.name || questId),
    ...diffArray('活跃事件', before.world.activeEventIds, after.world.activeEventIds, eventId => eventId),
  ].slice(0, 18);
}

export function buildActionTrace(before: GameSave, after: GameSave, action: GameAction, outcome: ActionResult): ActionTrace {
  const involved = Array.from(
    new Set([
      getLocation(after.world.currentLocationId)?.name || after.world.currentLocationId,
      ...nameForActionTarget(action),
    ]),
  ).filter(Boolean);

  return {
    id: createId('trace'),
    createdAt: nowMs(),
    actionType: action.type,
    title: ACTION_LABELS[action.type] || action.type,
    ok: outcome.ok,
    tone: outcome.tone,
    message: outcome.message,
    beforeSummary: buildSituationSummary(before),
    afterSummary: buildSituationSummary(after),
    stateChanges: compactChanges(before, after),
    involved,
  };
}

function unsummarizedNarrativeText(save: GameSave): string {
  const summarizedUntil = save.narrative.summaryCount * 10;
  const entries = save.narrative.entries
    .filter(entry => entry.index > summarizedUntil)
    .sort((lhs, rhs) => lhs.index - rhs.index);

  if (!entries.length) return '暂无未总结日志。';

  return entries
    .map(entry =>
      [
        `第${entry.index}条 / ${entry.title}`,
        `地点:${entry.locationName || entry.locationId || '未知'}`,
        `行动:${entry.actionMessage}`,
        `状态变化:${entry.trace?.stateChanges.join('；') || '无'}`,
        entry.text,
      ].join('\n'),
    )
    .join('\n\n---\n\n');
}

function buildMemoryPack(save: GameSave, trace: ActionTrace): string {
  return [
    '【裂隙纪元前端剧情记忆包】',
    '本段是前端正文代替酒馆聊天记录后的动态剧情材料，只提供上下文，不规定回复格式。',
    '',
    '【当前权威局势】',
    trace.afterSummary,
    '',
    '【最新大总结】',
    save.narrative.latestSummary || '暂无。',
    '',
    '【未总结日志】',
    unsummarizedNarrativeText(save),
  ].join('\n');
}

function buildLatestUserInput(trace: ActionTrace): string {
  return [
    '【前端操作】',
    `{{user}}执行：${trace.title}`,
    `前端结算：${trace.message}`,
    `涉及对象：${trace.involved.join('、') || '无'}`,
    '状态变化：',
    trace.stateChanges.length ? trace.stateChanges.map(change => `- ${change}`).join('\n') : '- 无显式数值变化',
    '',
    '【用户发言】',
    '{{user}}通过前端操作发起本轮行动，未输入额外口述。',
    '',
    '【本轮回复】',
    '请按当前酒馆预设的正文位置、格式与文风继续本轮回复，并承接前端结算结果。',
  ].join('\n');
}

function buildWorldbookScanKeywords(trace: ActionTrace): string[] {
  return [
    trace.title,
    trace.message,
    ...trace.involved,
    ...trace.stateChanges,
  ].filter(Boolean);
}

function localNarrativeFallback(save: GameSave, trace: ActionTrace): string {
  const location = getLocation(save.world.currentLocationId);
  const changes = trace.stateChanges.length ? trace.stateChanges.join('；') : '局势没有出现显式数值变化';
  return [
    `${save.player.name}在${location?.name || save.world.currentLocationId}完成了${trace.title}。`,
    `本次结算结果为：${trace.message}`,
    `可见变化：${changes}。`,
    '酒馆生成接口暂不可用，因此当前正文由前端本地兜底生成。',
  ].join('\n\n');
}

async function generateAirpNarrative(save: GameSave, trace: ActionTrace): Promise<{ text: string; deletedMessages: number }> {
  const mark = markCurrentChatTail();
  const fallback = localNarrativeFallback(save, trace);

  if (typeof generate !== 'function') {
    return { text: fallback, deletedMessages: 0 };
  }

  try {
    const text = await generate({
      generation_id: trace.id,
      user_input: buildLatestUserInput(trace),
      should_stream: true,
      max_chat_history: 0,
      injects: [
        {
          position: 'none',
          depth: 0,
          role: 'system',
          should_scan: true,
          content: buildWorldbookScanText(save, buildWorldbookScanKeywords(trace)),
        },
        {
          position: 'in_chat',
          depth: 0,
          role: 'system',
          should_scan: false,
          content: AIRP_AUTHORITY_PROMPT,
        },
        {
          position: 'in_chat',
          depth: 4,
          role: 'assistant',
          should_scan: false,
          content: buildMemoryPack(save, trace),
        },
      ],
    });
    const deletedMessages = save.narrative.keepTemporaryChat ? 0 : await cleanupChatMessagesAfter(mark);
    return { text: text.trim() || fallback, deletedMessages };
  } catch (error) {
    console.warn('[裂隙纪元] 正文生成失败，使用本地兜底正文', error);
    const deletedMessages = save.narrative.keepTemporaryChat ? 0 : await cleanupChatMessagesAfter(mark);
    return { text: fallback, deletedMessages };
  }
}

function appendNarrative(save: GameSave, trace: ActionTrace, text: string, deletedMessages: number): GameSave {
  const location = getLocation(save.world.currentLocationId);
  const index = save.narrative.totalCount + 1;
  const entry: NarrativeEntry = {
    id: createId('airp'),
    index,
    createdAt: nowMs(),
    title: trace.title,
    text,
    actionType: trace.actionType,
    actionMessage: trace.message,
    locationId: save.world.currentLocationId,
    locationName: location?.name,
    tone: trace.tone,
    trace,
  };

  return {
    ...save,
    narrative: {
      ...save.narrative,
      entries: [entry, ...save.narrative.entries].slice(0, 120),
      totalCount: index,
      pendingSummary: index % 10 === 0,
      lastActionTrace: trace,
      lastCleanup: deletedMessages
        ? {
            createdAt: nowMs(),
            deletedMessages,
          }
        : save.narrative.lastCleanup,
    },
  };
}

function buildSummaryPrompt(save: GameSave, nextSummaryCount: number): string {
  const summarizedUntil = save.narrative.summaryCount * 10;
  const newEntries = save.narrative.entries
    .filter(entry => entry.index > summarizedUntil)
    .sort((lhs, rhs) => lhs.index - rhs.index);
  const logText = newEntries
    .map(entry =>
      [
        `## 正文${entry.index}`,
        `标题:${entry.title}`,
        `地点:${entry.locationName || entry.locationId || '未知'}`,
        `行动:${entry.actionMessage}`,
        `状态变化:${entry.trace?.stateChanges.join('；') || '无'}`,
        entry.text,
      ].join('\n'),
    )
    .join('\n\n');

  return [
    SUMMARY_CORE_PROMPT,
    '',
    `本次是第${nextSummaryCount}次大总结。`,
    '',
    '【之前的大总结】',
    save.narrative.latestSummary || '暂无。',
    '',
    '【本轮新增日志】',
    logText || '无新增日志。',
  ].join('\n');
}

async function generateSummary(save: GameSave): Promise<string> {
  const nextSummaryCount = Math.floor(save.narrative.totalCount / 10);
  const prompt = buildSummaryPrompt(save, nextSummaryCount);

  if (typeof generateRaw !== 'function') {
    return [
      '```',
      `大总结(${nextSummaryCount})`,
      '',
      '## 角色记忆',
      '',
      '暂无可用API总结。本地已记录正文日志，稍后可重新生成。',
      '',
      '## 核心事件时间线',
      '',
      `- 时间: 裂隙纪元${save.time.year}年${save.time.month}月${save.time.day}日`,
      '  - 事件经过: 前端完成第十条正文记录。',
      '```',
      '```',
      '角色表',
      '',
      `- ${save.player.name}: 主角、当前由玩家控制、位于${getLocation(save.world.currentLocationId)?.name || save.world.currentLocationId}`,
      '```',
    ].join('\n');
  }

  return generateRaw({
    generation_id: createId('summary'),
    user_input: prompt,
    should_silence: true,
    max_chat_history: 0,
    ordered_prompts: [
      {
        role: 'system',
        content: '你只负责根据用户输入中的日志生成大总结。不要创作新剧情。',
      },
      'user_input',
    ],
  });
}

async function summarizeIfDue(save: GameSave): Promise<GameSave> {
  const nextSummaryCount = Math.floor(save.narrative.totalCount / 10);
  if (save.narrative.totalCount < 10 || nextSummaryCount <= save.narrative.summaryCount) {
    return { ...save, narrative: { ...save.narrative, pendingSummary: false } };
  }

  try {
    const summary = await generateSummary(save);
    return {
      ...save,
      narrative: {
        ...save.narrative,
        latestSummary: summary.trim(),
        summaryCount: nextSummaryCount,
        pendingSummary: false,
      },
    };
  } catch (error) {
    console.warn('[裂隙纪元] 大总结生成失败', error);
    return {
      ...save,
      narrative: {
        ...save.narrative,
        pendingSummary: true,
      },
    };
  }
}

export async function runAirpPipeline(save: GameSave, trace: ActionTrace): Promise<GameSave> {
  const generated = await generateAirpNarrative(save, trace);
  const withNarrative = appendNarrative(save, trace, generated.text, generated.deletedMessages);
  return summarizeIfDue(withNarrative);
}
