import { getItem } from '../data/catalog';
import { appendLog } from '../core/save';
import type { GameSave, Tone } from '../core/types';
import { clampPercent } from './common';
import { changeInventory } from './inventoryEngine';
import { advanceTime } from './timeEngine';

export function rest(save: GameSave, hours: number): GameSave {
  const nextSave = advanceTime(save, hours * 60);
  return appendLog(
    {
      ...nextSave,
      player: {
        ...nextSave.player,
        hp: clampPercent(nextSave.player.hp + 8 * hours),
        mp: clampPercent(nextSave.player.mp + 12 * hours),
        sp: clampPercent(nextSave.player.sp + 6 * hours),
        fatigue: hours >= 6 ? '精力充沛' : '轻微疲劳',
      },
    },
    'green',
    '休整',
    hours >= 6 ? '你睡了一整段时间，状态明显恢复。' : '你进行了短暂休整。',
  );
}

export function eat(save: GameSave, itemId = 'ration'): { save: GameSave; ok: boolean; tone: Tone; message: string } {
  const item = getItem(itemId);
  if (!item) return { save, ok: false, tone: 'red', message: '未知食物。' };

  let nextSave = save;
  if ((save.inventory.items[itemId] || 0) > 0) {
    nextSave = changeInventory(save, itemId, -1);
  } else if (save.player.credits >= item.price) {
    nextSave = { ...save, player: { ...save.player, credits: save.player.credits - item.price } };
  } else {
    return { save, ok: false, tone: 'red', message: '没有食物，也没有足够信点购买。' };
  }

  nextSave = appendLog(
    {
      ...advanceTime(nextSave, 30),
      player: { ...nextSave.player, hunger: '饱腹', hp: clampPercent(nextSave.player.hp + 4), sp: clampPercent(nextSave.player.sp + 4) },
    },
    'green',
    '进食',
    `你使用了${item.name}，饥饿状态恢复为饱腹。`,
  );
  return { save: nextSave, ok: true, tone: 'green', message: '已经进食。' };
}
