export const PROJECT_NAME = '裂隙纪元前端版';
export const SAVE_SCHEMA_VERSION = 1;
export const SAVE_VARIABLE_KEY = 'riftEraFrontendSave';
export const GameSaveSchema = z.object({
    schemaVersion: z.number(),
    saveId: z.string(),
    saveName: z.string(),
    createdAt: z.number(),
    savedAt: z.number(),
    lastTickAt: z.number(),
    stage: z.enum(['new', 'active', 'ended']),
    player: z.any(),
    time: z.any(),
    world: z.any(),
    inventory: z.any(),
    quests: z.any(),
    npcs: z.any(),
    factions: z.any(),
    titles: z.any(),
    events: z.any(),
    combat: z.any(),
    narrative: z.any().optional(),
    logs: z.array(z.any()),
    messages: z.array(z.any()),
    debug: z.any(),
}).passthrough();
