import { NPC_INTERACTION_RULES, getFaction, getNpc, getTitle, getWorldEvent } from '../data/catalog';
import { appendLog } from '../core/save';
import type { GameSave, NpcInteractionRuleDefinition, Tone } from '../core/types';
import { checkConditions } from './conditionEngine';
import { activateWorldEvents, completeWorldEvents } from './eventEngine';
import { applyFactionReputationRewards, grantFactionMemberships } from './factionEngine';
import { recordQuestEvent } from './questEngine';
import { grantTitles } from './titleEngine';
import { advanceTime } from './timeEngine';

const npcRuleFlag = (ruleId: string) => `npcInteraction:${ruleId}`;

function relationAttitude(favor: number): string {
  if (favor >= 100) return '深交';
  if (favor >= 60) return '信任';
  if (favor >= 30) return '好感';
  if (favor <= -50) return '厌恶';
  if (favor < 0) return '冷淡';
  return '中立';
}

function setNpcFavor(save: GameSave, npcId: string, delta: number): GameSave {
  const npc = getNpc(npcId);
  const current = save.npcs.relations[npcId] || { favor: npc?.defaultFavor || 0, attitude: '中立' };
  const favor = Math.max(-200, Math.min(200, current.favor + delta));
  return {
    ...save,
    npcs: {
      ...save.npcs,
      relations: {
        ...save.npcs.relations,
        [npcId]: {
          ...current,
          favor,
          attitude: relationAttitude(favor),
          lastTalkAt: Date.now(),
        },
      },
    },
  };
}

function markNpcRuleTriggered(save: GameSave, ruleId: string): GameSave {
  return {
    ...save,
    events: {
      ...save.events,
      flags: {
        ...save.events.flags,
        [npcRuleFlag(ruleId)]: true,
      },
    },
  };
}

export function getAvailableNpcInteractionRules(save: GameSave, npcId: string): NpcInteractionRuleDefinition[] {
  return NPC_INTERACTION_RULES.filter(rule => {
    if (rule.npcId !== npcId) return false;
    if (save.events.flags[npcRuleFlag(rule.id)]) return false;
    return checkConditions(save, rule.conditions).ok;
  });
}

function applyNpcRule(save: GameSave, rule: NpcInteractionRuleDefinition): { save: GameSave; summary: string } {
  let nextSave = save;
  if (rule.favorDelta) nextSave = setNpcFavor(nextSave, rule.npcId, rule.favorDelta);
  nextSave = applyFactionReputationRewards(nextSave, rule.factionReputation);
  nextSave = grantFactionMemberships(nextSave, rule.grantFactionMembershipIds);
  nextSave = grantTitles(nextSave, rule.rewardTitleIds);
  nextSave = activateWorldEvents(nextSave, rule.rewardEventIds);
  nextSave = completeWorldEvents(nextSave, rule.completeEventIds);
  nextSave = markNpcRuleTriggered(nextSave, rule.id);

  const factionText = Object.entries(rule.factionReputation || {})
    .map(([factionId, delta]) => `${getFaction(factionId)?.name || factionId}${delta >= 0 ? '+' : ''}${delta}`)
    .join('、');
  const titleText = (rule.rewardTitleIds || []).map(titleId => getTitle(titleId)?.name || titleId).join('、');
  const eventText = (rule.rewardEventIds || []).map(eventId => getWorldEvent(eventId)?.name || eventId).join('、');
  const pieces = [factionText && `声望 ${factionText}`, titleText && `称号 ${titleText}`, eventText && `事件 ${eventText}`].filter(Boolean);
  return { save: nextSave, summary: `${rule.name}${pieces.length ? `（${pieces.join('；')}）` : ''}` };
}

export function talkToNpc(save: GameSave, npcId: string): { save: GameSave; ok: boolean; tone: Tone; message: string } {
  const npc = getNpc(npcId);
  if (!npc) return { save, ok: false, tone: 'red', message: '未知NPC。' };
  if (npc.locationId !== save.world.currentLocationId) return { save, ok: false, tone: 'amber', message: `${npc.name}不在当前地点。` };

  let nextSave = setNpcFavor(advanceTime(save, 20), npcId, 3);
  const triggered: string[] = [];
  getAvailableNpcInteractionRules(nextSave, npcId).forEach(rule => {
    const applied = applyNpcRule(nextSave, rule);
    nextSave = applied.save;
    triggered.push(applied.summary);
  });

  nextSave = recordQuestEvent(recordQuestEvent(nextSave, 'npc_talk'), `npc_talk:${npcId}`);
  nextSave = appendLog(
    nextSave,
    'cyan',
    'NPC互动',
    triggered.length ? `你与${npc.name}交谈。好感 +3。触发：${triggered.join('；')}。` : `你与${npc.name}交谈。好感 +3。`,
  );
  return {
    save: nextSave,
    ok: true,
    tone: 'cyan',
    message: triggered.length ? `已与${npc.name}交谈。触发：${triggered.join('；')}。` : `已与${npc.name}交谈。`,
  };
}
